create or replace function public.merge_honors_seed(p_slug text, p_honors jsonb)
returns text language plpgsql as $fn$
declare
  v_blocks jsonb; v_base jsonb; v_after jsonb := '[]'::jsonb; v_end jsonb := '[]'::jsonb;
  v_head jsonb; v_tail jsonb; v_k int; e jsonb; v_is_end boolean; v_merged jsonb;
begin
  select content_blocks->'blocks' into v_blocks from lessons where slug = p_slug;
  if v_blocks is null then return p_slug || ': NO LESSON'; end if;
  select coalesce(jsonb_agg(x order by ord),'[]'::jsonb) into v_base
    from jsonb_array_elements(v_blocks) with ordinality t(x,ord)
    where coalesce(x->>'visibilityTrack','') <> 'honors';
  for e in select value from jsonb_array_elements(p_honors) loop
    v_is_end := (e->>'type'='marzano')
      or (e->>'type'='exit_ticket' and coalesce(e->>'prompt','') ~* '^[[:space:]]*(JUSTIFY|TRANSFER|PLAN|STATE|REBUTTAL|NAME THE ASSUMPTION)');
    if v_is_end then v_end := v_end || jsonb_build_array(e); else v_after := v_after || jsonb_build_array(e); end if;
  end loop;
  select count(*) into v_k from (
    select bool_and((x->>'type') in ('target','asteroid_thread'))
           over (order by ord rows between unbounded preceding and current row) as lead
    from jsonb_array_elements(v_base) with ordinality t(x,ord)) s where lead;
  select coalesce(jsonb_agg(x order by ord),'[]'::jsonb) into v_head
    from jsonb_array_elements(v_base) with ordinality t(x,ord) where ord <= v_k;
  select coalesce(jsonb_agg(x order by ord),'[]'::jsonb) into v_tail
    from jsonb_array_elements(v_base) with ordinality t(x,ord) where ord > v_k;
  v_merged := v_head || v_after || v_tail || v_end;
  update lessons set content_blocks = jsonb_set(coalesce(content_blocks,'{"schemaVersion":1}'::jsonb),'{blocks}',v_merged), updated_at = now()
    where slug = p_slug;
  return p_slug || ': base ' || jsonb_array_length(v_base) || ' + after ' || jsonb_array_length(v_after)
    || ' + end ' || jsonb_array_length(v_end) || ' (k=' || v_k || ') -> ' || jsonb_array_length(v_merged);
end $fn$;

select public.merge_honors_seed('u1-d01', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — the obstacle", "markdown": "The year opens on the thing standing in our way. Watch the demo, and **bet before you see it.**"}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## The string that breaks where you don't expect\n\nA heavy mass hangs from a thin string; an identical string hangs from its underside with a handle.\n\n- Pull the bottom **slowly** → which string breaks?\n- Pull the bottom with a sharp **jerk** → which string breaks?\n\nSame rig, opposite results — decided only by *how* you pull.\n\n*Safety: your teacher runs this in a bounded, padded zone. Do not rebuild it unsupervised.*"}, {"id": "h3", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "Slow pull: the ___ string breaks. Sharp jerk: the ___ string breaks, because ___.", "prompt": "PREDICT BEFORE THE PULL. For the slow pull and for the sharp jerk, which string breaks — and WHY? Commit before you see it."}, {"id": "h4", "type": "prose", "visibilityTrack": "honors", "markdown": "## Build the model\n\nSlow pull → the **top** string breaks (it carries your pull *plus* the weight). Sharp jerk → the **bottom** breaks: the mass's **inertia** won't let it accelerate fast enough to pass the sudden force up to the top string.\n\n**Inertia = a mass's resistance to a change in its motion** — not just 'how much stuff.' That resistance is the obstacle this whole year is up against."}, {"id": "h5", "type": "vocab", "visibilityTrack": "honors", "terms": [{"term": "inertia", "definition": "an object's resistance to any change in its motion; greater mass means greater inertia", "cognate": "inercia / inércia"}]}, {"id": "h6", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "The same rig gave opposite results because ___. 'The bottom string was just weaker' is wrong because ___.", "prompt": "JUSTIFY (homework): Explain, using inertia, why the same rig breaks differently depending on how you pull — and why 'the bottom string was weaker' is not an available answer."}, {"id": "h7", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "2026-XJ's mass (~3.5×10^11 kg) makes it hard to deflect because ___. The unit that will answer 'how big a push?' is ___.", "prompt": "TRANSFER (homework): Asteroid 2026-XJ has a mass around 3.5×10^11 kg. Using what 'inertia' meant today, explain why that mass is the obstacle to deflecting it — and name the unit you think will answer 'how big a push?'"}, {"id": "h8", "type": "callout", "visibilityTrack": "honors", "variant": "tip", "title": "Connect forward", "markdown": "That heavy mass that refused to move is the asteroid. We're the jerk on the string. Every unit from here asks one question: **can we move it anyway?**"}, {"id": "h9", "type": "marzano", "visibilityTrack": "honors", "capture": true, "targetId": "u1.d01-inertia-obstacle"}] $honors$::jsonb);
select public.merge_honors_seed('u1-d02', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — finish the string", "markdown": "Yesterday the two-string demo broke the room's prediction. Today we close the loop on it — not by re-watching, but by making the **assumptions** in your inertia explanation explicit. A model that can't say *when it would break* isn't finished."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## State your assumptions (and when they'd break)\n\nYour Day 1 explanation — *the jerk loads the bottom string faster than the mass's inertia lets it accelerate, so the force never reaches the top* — quietly assumes things. Good physicists name them.\n\nWhat the explanation assumes:\n- The strings are **identical** (same breaking strength). If the top string were secretly weaker, the result could flip — and it would no longer be an inertia story at all.\n- The pull on a **jerk** rises to the breaking force *faster* than the mass can begin moving. Pull slowly enough and the mass has time to accelerate, passing the load up — the **top** breaks instead.\n- The mass is **rigid** and the string **massless** — all the resistance comes from the hanging mass's inertia, not from stretch in the string.\n\n*A claim with no stated limits is just a guess that got lucky.*"}, {"id": "h3", "type": "callout", "visibilityTrack": "honors", "variant": "warning", "title": "When the model breaks", "markdown": "If you pulled the bottom string **slowly** but still saw it snap, your inertia explanation would be in trouble. Naming that failure condition *in advance* is what separates a defended claim from a memorized one."}, {"id": "h4", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "The same rig breaks differently because of inertia — the mass resists ___. This explanation depends on the assumption that ___, and it would FAIL if ___.", "prompt": "JUSTIFY: Explain why the two-string rig breaks differently depending on how you pull, using inertia. Then name ONE assumption your explanation depends on and describe the observation that would prove the explanation wrong."}, {"id": "h5", "type": "callout", "visibilityTrack": "honors", "variant": "tip", "title": "Connect forward", "markdown": "**Mass resists change in motion.** That single sentence is the obstacle the whole year fights. 2026-XJ has an enormous mass, so it has enormous inertia — it will not be nudged easily. Every unit from here is one long attempt to move it anyway."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d03', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — graphs are claims", "markdown": "In Match-the-Graph you'll line up a motion to its position-time graph. CPA reads the graph. Honors reads it as a **claim about the world** — something that could be true or false — not just a picture to match."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## Read graphs as CLAIMS\n\nA position-time graph isn't decoration. It *asserts* specific things:\n\n- A **straight, rising line** claims: *this object moves at constant velocity, never speeding up or slowing down, over this whole interval.*\n- A **horizontal line** claims: *the object is at rest — its position does not change.*\n- A **curving** line claims: *the velocity itself is changing.*\n\nBecause each is a claim, each can be **falsified**. If you can describe a real motion the graph says is impossible — and then make that motion happen — you've proven the graph wrong. That's the honors move: don't just match the graph, *interrogate* what it forbids."}, {"id": "h3", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "This graph claims that ___. A motion that would make this graph FALSE is ___, because ___.", "prompt": "JUSTIFY: Pick one position-time graph from today. State the claim it makes about the motion. Then describe a specific motion that would make that graph FALSE — and explain how that motion contradicts what the graph asserts."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d04', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — name the hidden assumption", "markdown": "When you compute velocity as $v = \\Delta x / \\Delta t$, you get *average* velocity over the interval. Treating that one number as 'the velocity' smuggles in an assumption. Honors names it."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## The constant-velocity assumption\n\nSuppose 2026-XJ covers $1.2 \\times 10^6$ km in 140 seconds, so $v = \\Delta x / \\Delta t \\approx 8{,}570$ m/s. It's tempting to say 'the asteroid moves at 8,570 m/s.'\n\nBut $\\Delta x / \\Delta t$ only gives the **average** over that interval. Calling it *the* velocity assumes the object moved at the **same speed the entire time** — that it never sped up or slowed down. If anything pulled on it mid-interval, the average is still correct but it no longer describes any single moment.\n\nThe assumption is invisible until you say it out loud: *I am treating this velocity as constant across the interval.*"}, {"id": "h3", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "When I use $v = \\Delta x/\\Delta t$ I'm assuming ___. This assumption is safe when ___, but it would fail if ___.", "prompt": "NAME THE ASSUMPTION + JUSTIFY: You computed an average velocity today. State the assumption you make when you treat that average as 'the' velocity. Give one situation where the assumption is fine, and one where it would mislead you — and explain why."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d05', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — justify the decomposition", "markdown": "CPA breaks a vector into components using sine and cosine. Honors does the same — then defends **why** that trig is the right trig, instead of guessing which function goes where."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## Why sine, why cosine?\n\nFor a vector of magnitude $R$ at angle $\\theta$ measured from the **+x axis**:\n\n- $R_x = R\\cos\\theta$ — the **adjacent** side of the right triangle the vector forms.\n- $R_y = R\\sin\\theta$ — the **opposite** side.\n\nThe choice isn't a rule to memorize; it follows from *where you measured the angle from*. Measure $\\theta$ from the y-axis instead and sine and cosine swap. So before decomposing, the honors question is always: **what is my angle measured from, and which leg of the triangle is that?**\n\nThe components must also rebuild the original: $R = \\sqrt{R_x^2 + R_y^2}$. If they don't, the decomposition is wrong — a built-in check."}, {"id": "h3", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "I used $R_x = R\\cos\\theta$ and $R_y = R\\sin\\theta$ because my angle $\\theta$ was measured from ___, which makes the x-component the ___ side of the triangle. If the angle were measured from ___ instead, I would ___.", "prompt": "JUSTIFY: For 2026-XJ's velocity at an angle, you split it into components. Explain WHY you assigned cosine to one axis and sine to the other — tie it to where the angle is measured from and which side of the right triangle each component is."}, {"id": "h4", "type": "callout", "visibilityTrack": "honors", "variant": "warning", "title": "State the assumption", "markdown": "Decomposing into perpendicular x and y components assumes those two axes are **independent** — motion along x doesn't affect motion along y. That independence is what lets us treat a 2-D problem as two separate 1-D problems. It's a powerful assumption; name it, because later (projectiles, forces on the asteroid) it's exactly the assumption that does the heavy lifting."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d06', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — what does the slope MEAN?", "markdown": "On a velocity-time graph, the slope is the acceleration. CPA reads off the number. Honors defends what that number *is* — and refuses the common slip that confuses a high velocity with a high acceleration."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## Reading an a-t story from a v-t graph\n\nThe slope of a velocity-time graph is $a = \\Delta v / \\Delta t$ — **how fast the velocity is changing**, not how fast the object is going.\n\n- A **steep** v-t line claims large acceleration: velocity changing quickly.\n- A **flat (horizontal)** v-t line claims **zero** acceleration — even if the object is moving fast. Constant velocity means no change, means no acceleration.\n- A **negative** slope claims the object is slowing (or speeding up in the negative direction).\n\nThe honors trap to avoid: *'it's moving fast, so it's accelerating fast.'* Wrong. A spacecraft cruising at 10,000 m/s with a flat v-t line has **zero** acceleration. Speed lives on the axis; acceleration lives in the slope."}, {"id": "h3", "type": "callout", "visibilityTrack": "honors", "variant": "misconception", "title": "Common slip", "markdown": "*'High velocity means high acceleration.'* No. A high, **flat** v-t line is fast but unaccelerated. Acceleration is the *change*, the slope — not the height of the line."}, {"id": "h4", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "On this v-t graph the slope is ___, which means the acceleration is ___. A classmate who says the fast-moving object 'must be accelerating a lot' is wrong because ___.", "prompt": "JUSTIFY: Point to a segment of today's velocity-time graph and state what its slope means physically. Then refute a classmate who claims a fast-moving object on a flat v-t line is accelerating — explain what the flat slope actually tells you."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d07', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — justify WHICH equation", "markdown": "There are several kinematic equations and they all look plausible. CPA plugs into the one that works. Honors chooses on purpose — and can say why the others don't apply."}, {"id": "h2", "type": "prose", "visibilityTrack": "honors", "markdown": "## Pick the equation by what's missing\n\nThe constant-acceleration equations each leave out exactly one variable:\n\n- $v = v_0 + at$ — no displacement $\\Delta x$.\n- $\\Delta x = v_0 t + \\tfrac{1}{2}at^2$ — no final velocity $v$.\n- $v^2 = v_0^2 + 2a\\,\\Delta x$ — no time $t$.\n\nSo the honest selection rule is: **list your knowns, identify your unknown, and pick the equation that contains your unknown and none of the variables you don't have.** You're not hunting for a formula that 'works' — you're matching the equation to the information you actually possess.\n\nAnd every one of them rests on one assumption: **acceleration is constant** over the interval. If $a$ changes, none of these apply."}, {"id": "h3", "type": "gewa", "visibilityTrack": "honors", "capture": true, "prompt": "A probe starts at $v_0 = 200$ m/s and accelerates uniformly at $a = 12$ m/s² over a displacement of $\\Delta x = 5{,}000$ m. Find its final velocity. In your work, FIRST state which kinematic equation you chose and WHY the other two don't fit this problem.", "givenHint": "You have v0, a, and Δx — and you are NOT given time t.", "equationHint": "Choose the equation that contains your unknown (v) and does NOT require the variable you're missing (t).", "equationOptions": ["v = v₀ + at", "Δx = v₀t + ½at²", "v² = v₀² + 2aΔx"]}, {"id": "h4", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "I chose $v^2 = v_0^2 + 2a\\Delta x$ because my knowns were ___ and my unknown was ___, and the other equations failed because ___. All of these assume ___.", "prompt": "JUSTIFY: Explain how you decided WHICH kinematic equation to use for the probe problem — name the variable that was missing and how that ruled the others out. Then name the assumption all three equations share."}] $honors$::jsonb);
select public.merge_honors_seed('u1-d08', $honors$ [{"id": "h1", "type": "callout", "visibilityTrack": "honors", "variant": "note", "title": "Honors — carry the model to the asteroid", "markdown": "You can now solve a constant-acceleration problem. The honors demand isn't another plug-in — it's dropping that model onto a problem you haven't seen, the one the whole year is about."}, {"id": "h2", "type": "asteroid_thread", "visibilityTrack": "honors", "whatWeKnow": "We have the kinematic equations for constant acceleration and we can choose the right one and defend the choice.", "connection": "A deflection plan would give 2026-XJ a small, steady push — a constant acceleration — over a long time. Today you reason about whether that's even enough to matter, using only Unit 1's tools, and you name what those tools still can't answer."}, {"id": "h3", "type": "exit_ticket", "visibilityTrack": "honors", "capture": true, "frame": "Using $\\Delta x = v_0 t + \\tfrac{1}{2}at^2$, a tiny steady acceleration over a long time produces ___, which is why ___. But Unit 1 alone cannot tell me ___, because ___.", "prompt": "TRANSFER: Suppose a thruster could give 2026-XJ a tiny but constant sideways acceleration for the entire year before arrival. Using constant-acceleration reasoning (not a memorized number), explain why even a small acceleration applied over a very long time can build into a meaningful sideways displacement. Then name ONE thing Unit 1's kinematics still CANNOT answer about this deflection — and which later idea (force? mass thrown off? energy?) would be needed to answer it."}, {"id": "h4", "type": "callout", "visibilityTrack": "honors", "variant": "tip", "title": "Close forward", "markdown": "Kinematics tells us *what a motion does* if we already know the acceleration. It never tells us **what causes** that acceleration, or how big a push it takes to produce it. That 'how big a push?' question is the door into the next unit — Newton's laws and $F = ma$. The deflection story is just getting started."}, {"id": "h5", "type": "marzano", "visibilityTrack": "honors", "capture": true, "targetId": "u1.d08-kinematics-transfer"}] $honors$::jsonb);
